package execproxy_test

import (
	"context"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/egdaemon/eg/interp/execproxy"
	"github.com/stretchr/testify/require"
)

// DO NOT EDIT: This file was auto generated by egautotest.

func TestExec(t *testing.T) {
	t.Run("runs a successful command", func(t *testing.T) {
		proxy := execproxy.NewExecProxy(t.TempDir(), nil)
		resp, err := proxy.Exec(t.Context(), &execproxy.ExecRequest{
			Cmd: "/bin/true",
			Dir: t.TempDir(),
		})
		require.NoError(t, err)
		require.NotNil(t, resp)
	})

	t.Run("resolves relative dir against proxy root", func(t *testing.T) {
		root := t.TempDir()
		subdir := filepath.Join(root, "sub")
		require.NoError(t, os.MkdirAll(subdir, 0o755))

		proxy := execproxy.NewExecProxy(root, nil)
		_, err := proxy.Exec(t.Context(), &execproxy.ExecRequest{
			Cmd:       "/bin/sh",
			Arguments: []string{"-c", "touch marker"},
			Dir:       "sub",
		})
		require.NoError(t, err)
		require.FileExists(t, filepath.Join(subdir, "marker"))
	})

	t.Run("uses absolute dir as-is", func(t *testing.T) {
		absDir := t.TempDir()
		proxy := execproxy.NewExecProxy(t.TempDir(), nil)
		_, err := proxy.Exec(t.Context(), &execproxy.ExecRequest{
			Cmd:       "/bin/sh",
			Arguments: []string{"-c", "touch marker"},
			Dir:       absDir,
		})
		require.NoError(t, err)
		require.FileExists(t, filepath.Join(absDir, "marker"))
	})

	t.Run("passes proxy environ to command", func(t *testing.T) {
		dir := t.TempDir()
		proxy := execproxy.NewExecProxy(dir, []string{"MY_VAR=hello"})
		_, err := proxy.Exec(t.Context(), &execproxy.ExecRequest{
			Cmd:       "/bin/sh",
			Arguments: []string{"-c", `echo -n "$MY_VAR" > out.txt`},
			Dir:       dir,
		})
		require.NoError(t, err)
		data, err := os.ReadFile(filepath.Join(dir, "out.txt"))
		require.NoError(t, err)
		require.Equal(t, "hello", string(data))
	})

	t.Run("appends request environment after proxy environ", func(t *testing.T) {
		dir := t.TempDir()
		proxy := execproxy.NewExecProxy(dir, []string{"MY_VAR=base"})
		_, err := proxy.Exec(t.Context(), &execproxy.ExecRequest{
			Cmd:         "/bin/sh",
			Arguments:   []string{"-c", `echo -n "$MY_VAR" > out.txt`},
			Dir:         dir,
			Environment: []string{"MY_VAR=override"},
		})
		require.NoError(t, err)
		data, err := os.ReadFile(filepath.Join(dir, "out.txt"))
		require.NoError(t, err)
		require.Equal(t, "override", string(data))
	})

	t.Run("returns error when command exits non-zero", func(t *testing.T) {
		proxy := execproxy.NewExecProxy(t.TempDir(), nil)
		resp, err := proxy.Exec(t.Context(), &execproxy.ExecRequest{
			Cmd:       "/bin/sh",
			Arguments: []string{"-c", "exit 3"},
			Dir:       t.TempDir(),
		})
		require.Error(t, err)
		require.Nil(t, resp)
	})

	t.Run("returns error for non-existent command", func(t *testing.T) {
		proxy := execproxy.NewExecProxy(t.TempDir(), nil)
		resp, err := proxy.Exec(t.Context(), &execproxy.ExecRequest{
			Cmd: "/nonexistent/command/xyz123",
			Dir: t.TempDir(),
		})
		require.Error(t, err)
		require.Nil(t, resp)
	})

	t.Run("respects context cancellation", func(t *testing.T) {
		ctx, cancel := context.WithCancel(t.Context())
		proxy := execproxy.NewExecProxy(t.TempDir(), nil)
		go func() {
			time.Sleep(100 * time.Millisecond)
			cancel()
		}()
		resp, err := proxy.Exec(ctx, &execproxy.ExecRequest{
			Cmd:       "/bin/sleep",
			Arguments: []string{"30"},
			Dir:       t.TempDir(),
		})
		require.Error(t, err)
		require.Nil(t, resp)
	})
}
